331						return false
332					}
333					name, ok := key.(string)
334					if !ok || seen[name] {
335						return false
336					}
337					seen[name] = true
338					if !walk() {
339						return false
340					}
341				}
342				_, err := dec.Token()
343				return err == nil
344			case '[':
345				for dec.More() {
346					if !walk() {
347						return false
348					}
349				}
350				_, err := dec.Token()
351				return err == nil
352			}
353			return false
354		}
