1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"mime"
8		"net/http"
9		"net/url"
10		"sort"
11		"strings"
12		"sync"
13		"time"
14	)
15	
16	// maxProviderBody bounds the wire size of a provider publication body. The
17	// body holds at most 16 URLs, so a megabyte is ample slack.
18	const maxProviderBody = 1 << 20
19	
20	// maxProviderAddresses is the largest number of distinct addresses accepted
21	// in one publication.
22	const maxProviderAddresses = 16
23	
24	// maxProviderTTL bounds how far in the future a publication may expire.
25	const maxProviderTTL = 24 * time.Hour
26	
27	// providerRecord is one node's published access locations for a content
28	// identifier. Records live in process memory only: they take no part in
29	// pinning, garbage collection or storage statistics and are not preserved
30	// across restarts.
31	type providerRecord struct {
32		addresses []string
33		expiresAt time.Time
34	}
35	
36	// validProvider reports whether the record is in force at now.
37	func (p providerRecord) validProvider(now time.Time) bool {
38		return p.expiresAt.After(now)
39	}
40	
41	// providerDirectory maps content identifiers to per-node publication
42	// records. The directory never requires the object to be stored locally.
43	// All checks and mutations happen under one lock, so publication, lookup
44	// and deletion observe one consistent instant and concurrent first
45	// publications for one key are serialized.
46	type providerDirectory struct {
47		mu      sync.RWMutex
48		records map[string]map[string]providerRecord
49	}
50	
51	func newProviderDirectory() *providerDirectory {
52		return &providerDirectory{records: make(map[string]map[string]providerRecord)}
53	}
54	
55	// put publishes or replaces the record for cid/providerID. It reports
56	// created == true when no valid record existed at now (absent or already
57	// expired). The check and the write are one atomic operation.
58	func (d *providerDirectory) put(cid, providerID string, addresses []string, expiresAt, now time.Time) (providerRecord, bool) {
59		d.mu.Lock()
60		defer d.mu.Unlock()
61		byCID := d.records[cid]
62		if byCID == nil {
63			byCID = make(map[string]providerRecord)
64			d.records[cid] = byCID
65		}
66		rec := providerRecord{
67			addresses: append([]string{}, addresses...),
68			expiresAt: expiresAt,
69		}
70		existing, found := byCID[providerID]
71		created := !found || !existing.validProvider(now)
72		byCID[providerID] = rec
73		return rec, created
74	}
75	
76	// remove deletes the record for cid/providerID, reporting whether a valid
77	// record existed at now. Expired records are removed lazily and reported
78	// as absent.
79	func (d *providerDirectory) remove(cid, providerID string, now time.Time) bool {
80		d.mu.Lock()
81		defer d.mu.Unlock()
82		byCID := d.records[cid]
83		rec, found := byCID[providerID]
84		if !found || !rec.validProvider(now) {
85			delete(byCID, providerID)
86			return false
87		}
88		delete(byCID, providerID)
89		if len(byCID) == 0 {
90			delete(d.records, cid)
91		}
92		return true
93	}
94	
95	// providerEntry is one valid record as seen by a snapshot listing.
96	type providerEntry struct {
97		providerID string
98		addresses  []string
99		expiresAt  time.Time
100	}
101	
102	// list returns the records in force for cid at now, sorted by providerID.
103	// The slice is taken under one read-lock hold and every address slice is
104	// copied, so the result is a point-in-time snapshot the caller owns.
105	func (d *providerDirectory) list(cid string, now time.Time) []providerEntry {
106		d.mu.RLock()
107		defer d.mu.RUnlock()
108		entries := []providerEntry{}
109		for providerID, rec := range d.records[cid] {
110			if !rec.validProvider(now) {
111				continue
112			}
113			entries = append(entries, providerEntry{
114				providerID: providerID,
115				addresses:  append([]string{}, rec.addresses...),
116				expiresAt:  rec.expiresAt,
117			})
118		}
119		sort.Slice(entries, func(i, j int) bool { return entries[i].providerID < entries[j].providerID })
120		return entries
121	}
122	
123	// providerResponse is the JSON encoding of one published record.
124	type providerResponse struct {
125		ProviderID string    `json:"providerId"`
126		Addresses  []string  `json:"addresses"`
127		ExpiresAt  time.Time `json:"expiresAt"`
128	}
129	
130	// providerListResponse is the JSON body of GET /v1/providers/{cid}.
131	type providerListResponse struct {
132		CID       string             `json:"cid"`
133		Providers []providerResponse `json:"providers"`
134	}
135	
136	// providerPutRequest is the strictly decoded body of PUT
137	// /v1/providers/{cid}/{providerId}. Pointer fields distinguish a missing
138	// or null key from a value; address elements are pointers so null entries
139	// count as type errors.
140	type providerPutRequest struct {
141		Addresses *[]*string `json:"addresses"`
142		ExpiresAt *string    `json:"expiresAt"`
143	}
144	
145	// providersByCID handles GET /v1/providers/{cid}.
146	func (d *providerDirectory) providersByCID(w http.ResponseWriter, r *http.Request) {
147		if r.Method != http.MethodGet {
148			w.Header().Set("Allow", http.MethodGet)
149			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
150			return
151		}
152		cid := r.PathValue("cid")
153		if !validCID(cid) {
154			writeError(w, http.StatusBadRequest, "invalid_cid")
155			return
156		}
157		entries := d.list(cid, time.Now())
158		providers := make([]providerResponse, 0, len(entries))
159		for _, e := range entries {
160			providers = append(providers, providerResponse{
161				ProviderID: e.providerID,
162				Addresses:  e.addresses,
163				ExpiresAt:  e.expiresAt,
164			})
165		}
166		writeJSON(w, http.StatusOK, providerListResponse{CID: cid, Providers: providers})
167	}
168	
169	// providerByID handles PUT and DELETE on /v1/providers/{cid}/{providerId}.
170	func (d *providerDirectory) providerByID(w http.ResponseWriter, r *http.Request) {
171		switch r.Method {
172		case http.MethodPut:
173			d.putProvider(w, r)
174		case http.MethodDelete:
175			d.deleteProvider(w, r)
176		default:
177			w.Header().Set("Allow", "PUT, DELETE")
178			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
179		}
180	}
181	
182	// putProvider handles PUT /v1/providers/{cid}/{providerId}.
183	func (d *providerDirectory) putProvider(w http.ResponseWriter, r *http.Request) {
184		cid := r.PathValue("cid")
185		if !validCID(cid) {
186			writeError(w, http.StatusBadRequest, "invalid_cid")
187			return
